using System;
using System.Collections.Generic;
using Newtonsoft.Json;

namespace LastHearth.Core
{
    /// <summary>
    /// All numbers of the game. Generated by hearth/tools/economy.py into Resources/balance.json
    /// from the same model whose checks pass in docs/ECONOMY.md. Never edit the JSON by hand.
    /// </summary>
    public sealed class Balance
    {
        public int Version;
        public int MaxHearthLevel;
        public List<HearthLevelData> HearthLevels = new List<HearthLevelData>();
        public List<long> WarehouseStorage = new List<long>();
        public double SilverShare;
        public RulesData Rules = new RulesData();
        public BuildData Build = new BuildData();
        public double OfflineCapHours;
        public StarterData Starter = new StarterData();
        public WarmthData Warmth = new WarmthData();
        public List<HearthModeData> HearthModes = new List<HearthModeData>();
        public double CoalPerWarmthHour;
        public double FoodPerDwellerHour;
        public DwellerData Dwellers = new DwellerData();
        public HeroData Heroes = new HeroData();
        public List<long[]> SpeedupPoints = new List<long[]>();
        public ProductionData Production = new ProductionData();
        public List<RoomData> Rooms = new List<RoomData>();
        public GridData Grid = new GridData();
        public ObstacleData Obstacles = new ObstacleData();
        public MergeData Merge = new MergeData();
        public BirthData Births = new BirthData();
        /// <summary>GDD 10: hearth levels that open the 6th-9th squad slots.</summary>
        public int[] SquadSlots = new int[0];
        public ActivitiesData Activities = new ActivitiesData();
        public CampaignData Campaign = new CampaignData();

        public static Balance FromJson(string json)
        {
            var balance = JsonConvert.DeserializeObject<Balance>(json);
            if (balance == null || balance.HearthLevels.Count != balance.MaxHearthLevel - 1)
                throw new FormatException("balance.json is broken: expected a row for every hearth level");
            return balance;
        }

        /// <summary>Row of hearth level L (1-based): room jobs to level L and the hearth job L -> L+1.</summary>
        public HearthLevelData Level(int level)
        {
            if (level < 1 || level > HearthLevels.Count)
                throw new ArgumentOutOfRangeException(nameof(level));
            return HearthLevels[level - 1];
        }

        public RoomData Room(RoomType type)
        {
            foreach (var room in Rooms)
            {
                if (room.Type == type)
                    return room;
            }
            throw new KeyNotFoundException(type.ToString());
        }

        public HearthModeData Mode(HearthMode mode)
        {
            foreach (var m in HearthModes)
            {
                if (m.Mode == mode)
                    return m;
            }
            throw new KeyNotFoundException(mode.ToString());
        }

        /// <summary>Silver + iron the warehouse holds at this warehouse level.</summary>
        public long StorageAt(int warehouseLevel)
        {
            int i = Math.Max(1, Math.Min(warehouseLevel, WarehouseStorage.Count)) - 1;
            return WarehouseStorage[i];
        }

        public double ProductionBase(ResourceType resource, int roomLevel)
        {
            var table = Production.Base[resource.ToString()];
            int i = Math.Max(1, Math.Min(roomLevel, table.Length)) - 1;
            return table[i];
        }
    }

